{
  "claim": "For non-headline series with an available panel, one provider, infrequent middle-provider repricing, and gate14=false, fm2 alone will reduce pinball loss relative to the current system.",
  "mechanism": "With one provider, coordinated changes to that provider's offers can move the published median without being diluted by other providers. When repricing is infrequent, fm2's 16-day context and last-value centre should preserve the latest price level while limiting uncertainty inherited from older pricing regimes.",
  "spec": {
    "when": {
      "all": [
        {"fact": "in37", "op": "==", "value": false},
        {"fact": "gate14", "op": "==", "value": false},
        {"fact": "has_panel", "op": "==", "value": true},
        {"fact": "p_providers", "op": "<", "value": 2},
        {"fact": "mid_prov_reprice21", "op": "<", "value": 0.0952}
      ]
    },
    "do": {
      "action": "members_only",
      "members": ["fm2"]
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 90% of the ISO-week bootstrap resamples show improvement, fewer than 200 cells across five series change, or headline skill falls.",
  "prior_ids_used": [],
  "expects": "A modest pooled-skill gain, motivated by fm2's +0.273 skill versus the system's +0.251 in the reported broader single-provider, low-repricing slice of 1,918 cells across 70 series. Headline forecasts remain unchanged by construction; the report does not establish whether the non-headline subset will satisfy the change-count, temporal-stability, or bootstrap requirements."
}
